{
  "story": "Why might a lower prediction earn the next trial? Review completed trials, then inspect Settings A and B. This fixed, noiseless example maximizes score using expected improvement: average positive gain above the best observed score. Gaussian predictions are supplied, not fitted here. Use Next; the decision remains visible until you act.",
  "aha": {
    "stateId": "choose-b",
    "observation": "Setting B wins because its uncertainty creates more expected improvement, despite its lower predicted score."
  },
  "layout": {
    "preset": "approved-card",
    "width": 640
  },
  "parts": [
    {
      "id": "decision-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and above the experiment. Highlight the active state; keep all progress on this rail. Steps represent decisions, not elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "settings-picture",
      "kind": "fixed-picture",
      "presentation": "Use one fixed row with three named regions. Only the active region changes highlight. Keep labels readable without motion or a matrix.",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "links": "variant.links"
      }
    },
    {
      "id": "decision-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the active region without covering labels. Identify the setting and explain its role; report numerical values only in readouts.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "decision-evidence",
      "kind": "value-readout",
      "presentation": "Show one active-setting evidence stack, not a candidate matrix. Scores, uncertainty, and expected improvement share score-point units. Uncertainty denotes one standard deviation. Expected improvement is computed from each Gaussian forecast against the same observed best. Round displayed numbers to two decimals. Keep the observed-best readout anchored. Use the final entry as the bound status line.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Decision step",
      "presentation": "Parameter-control budget: zero; navigation and reset are separate. Provide Previous and Next, moving exactly one state per action. Default to the first state; bounds are the first and last states. Retain button names when disabled at boundaries. Every state persists until another action; never advance automatically. Use visible keyboard focus and native keyboard activation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide visible focus and keyboard activation. Reference captures must show the named aha state."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Expected improvement with fixed Gaussian forecasts",
        "regions": [
          {
            "id": "completed",
            "label": "Completed trials",
            "values": [
              "Observed baseline"
            ]
          },
          {
            "id": "setting-a",
            "label": "Setting A",
            "values": [
              "Untried candidate"
            ]
          },
          {
            "id": "setting-b",
            "label": "Setting B",
            "values": [
              "Untried candidate"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "observed-best",
            "label": "Observed best",
            "short": "Baseline",
            "sentence": "Completed trials establish the result to beat.",
            "why": "Expected improvement counts only gains above this baseline; worse outcomes contribute zero improvement.",
            "active": [
              "completed"
            ],
            "calloutRegion": "completed",
            "readouts": [
              {
                "id": "best",
                "label": "Best observed score",
                "value": "8.00"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Compare the two untried settings next."
              }
            ]
          },
          {
            "id": "inspect-a",
            "label": "Inspect A",
            "short": "Setting A",
            "sentence": "Setting A predicts a modest, fairly certain improvement.",
            "why": "Its narrow uncertainty keeps most possible outcomes close to its predicted score.",
            "active": [
              "setting-a"
            ],
            "calloutRegion": "setting-a",
            "readouts": [
              {
                "id": "best",
                "label": "Best observed score",
                "value": "8.00"
              },
              {
                "id": "prediction",
                "label": "A predicted score",
                "value": "8.50"
              },
              {
                "id": "uncertainty",
                "label": "A uncertainty",
                "value": "0.20"
              },
              {
                "id": "a-improvement",
                "label": "A expected improvement",
                "value": "0.50"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Inspect Setting B before choosing."
              }
            ]
          },
          {
            "id": "choose-b",
            "label": "Choose next",
            "short": "Setting B",
            "sentence": "Setting B is the next trial.",
            "why": "Its wider uncertainty offers enough upside to outweigh its lower predicted score.",
            "active": [
              "setting-b"
            ],
            "calloutRegion": "setting-b",
            "readouts": [
              {
                "id": "best",
                "label": "Best observed score",
                "value": "8.00"
              },
              {
                "id": "prediction",
                "label": "B predicted score",
                "value": "8.00"
              },
              {
                "id": "uncertainty",
                "label": "B uncertainty",
                "value": "2.00"
              },
              {
                "id": "a-improvement",
                "label": "A expected improvement",
                "value": "0.50"
              },
              {
                "id": "b-improvement",
                "label": "B expected improvement",
                "value": "0.80"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Choose B: highest expected improvement among these candidates."
              }
            ]
          }
        ]
      }
    ]
  }
}
